import math

def log_loss(labels, probabilities):
    if not labels:
        return 0.0
    losses=[]
    for y,p in zip(labels,probabilities):
        p=min(max(p,1e-12),1-1e-12)
        losses.append(-math.log(p) if y else -math.log(1-p))
    return sum(losses)/len(losses)

def split_gini(left, right):
    total=len(left)+len(right)
    if not total:
        return 0.0
    result=0.0
    for child in (left,right):
        if child:
            p=sum(child)/len(child)
            result += len(child)/total * (1-p*p-(1-p)*(1-p))
    return result

def ridge_objective(predictions, targets, weights, alpha):
    mse=sum((p-y)**2 for p,y in zip(predictions,targets))/len(targets) if targets else 0.0
    return mse+alpha*sum(w*w for w in weights)

def select_model(train_y, valid_y, candidates):
    def mse(y,p):
        return sum((a-b)**2 for a,b in zip(y,p))/len(y)
    scores=[{"train":mse(train_y,c["train"]),"validation":mse(valid_y,c["valid"])} for c in candidates]
    best=min(range(len(scores)),key=lambda i:scores[i]["validation"])
    return {"best":best,"scores":scores}

def metrics(labels, predictions):
    tp=sum(y==1 and p==1 for y,p in zip(labels,predictions))
    fp=sum(y==0 and p==1 for y,p in zip(labels,predictions))
    fn=sum(y==1 and p==0 for y,p in zip(labels,predictions))
    return {"precision":tp/(tp+fp) if tp+fp else 0.0,"recall":tp/(tp+fn) if tp+fn else 0.0,"f1":2*tp/(2*tp+fp+fn) if 2*tp+fp+fn else 0.0}

def choose_threshold(labels, probabilities, thresholds):
    best=None
    for threshold in thresholds:
        pred=[int(p>=threshold) for p in probabilities]
        tp=sum(y==1 and p==1 for y,p in zip(labels,pred))
        fp=sum(y==0 and p==1 for y,p in zip(labels,pred))
        fn=sum(y==1 and p==0 for y,p in zip(labels,pred))
        den=2*tp+fp+fn
        f1=2*tp/den if den else 0.0
        if best is None or f1>best["f1"]:
            best={"threshold":threshold,"f1":f1}
    return best

