exercise.solution:
def prepare_documents(records):
    return [[len(r["text"].split()),r["text"].count("!")] for r in records], [r["label"] for r in records]

def fit_centroids(X, y):
    state={}
    for label in (0,1):
        rows=[row for row,target in zip(X,y) if target==label]
        if not rows:
            raise ValueError("Both classes need training examples")
        state[label]=[sum(row[j] for row in rows)/len(rows) for j in range(2)]
    return state

