exercise.solution:
def squared_distance(a, b):
    return sum((x-y)**2 for x,y in zip(a,b))

def evaluate_centroids(state, X, y):
    pred=[int(squared_distance(row,state[1])<squared_distance(row,state[0])) for row in X]
    tp=sum(t==1 and p==1 for t,p in zip(y,pred))
    fp=sum(t==0 and p==1 for t,p in zip(y,pred))
    fn=sum(t==1 and p==0 for t,p in zip(y,pred))
    den=2*tp+fp+fn
    return {"predictions":pred,"f1":2*tp/den if den else 0.0,"errors":[i for i,(t,p) in enumerate(zip(y,pred)) if t!=p]}
